('prod_loja_0001_01', 'loja_0001', 'X-Tudo', 'Delicioso X-Tudo feito com molho especial da casa, bacon crocante e frango grelhado.', 49.27, 'Prato Principal', 'https://picsum.photos/seed/prod_loja_0001_01/200', true, '250g', 0, 293),
('prod_loja_0001_02', 'loja_0001', 'Tacos Mexicanos', 'Nosso Tacos Mexicanos combina vinagrete fresco, carne suína e parmesão ralado em uma explosão de sabor.', 14.94, 'Acompanhamento', 'https://picsum.photos/seed/prod_loja_0001_02/200', true, '250g', 0, 302),
('prod_loja_0001_03', 'loja_0001', 'Brigadeiro Gourmet', 'Nosso Brigadeiro Gourmet combina bacon crocante, tomate fresco e batata rústica em uma explosão de sabor.', 21.97, 'Sobremesas', 'https://picsum.photos/seed/prod_loja_0001_03/200', true, '250g', 0, 387),
('prod_loja_0001_04', 'loja_0001', 'Pão na Chapa', 'Pão na Chapa preparado com molho especial da casa, azeite extra virgem e molho branco.', 12.62, 'Combos', 'https://picsum.photos/seed/prod_loja_0001_04/200', true, '600ml', 0, 447),
('prod_loja_0001_05', 'loja_0001', 'Frango à Parmegiana', 'Delicioso Frango à Parmegiana feito com tomate fresco, carne bovina e couve refogada.', 58.64, 'Acompanhamento', 'https://picsum.photos/seed/prod_loja_0001_05/200', true, '500g', 0, 195),
('prod_loja_0001_06', 'loja_0001', 'Temaki de Salmão', 'Temaki de Salmão preparado com alface americana, milho verde e parmesão ralado.', 44.32, 'Saladas', 'https://picsum.photos/seed/prod_loja_0001_06/200', true, '500g', 0, 198),
('prod_loja_0001_07', 'loja_0001', 'Yakisoba Tradicional', 'Experimente nosso Yakisoba Tradicional, preparado com atum fresco, queijo cheddar e farofa crocante.', 47.34, 'Acompanhamento', 'https://picsum.photos/seed/prod_loja_0001_07/200', false, '450g', 0, 132),
('prod_loja_0001_08', 'loja_0001', 'Calabresa Acebolada', 'Calabresa Acebolada preparado com frango grelhado, carne bovina e atum fresco.', 69.23, 'Porções', 'https://picsum.photos/seed/prod_loja_0001_08/200', true, '500ml', 0, 442),
('prod_loja_0001_09', 'loja_0001', 'Carne de Sol com Macaxeira', 'Delicioso Carne de Sol com Macaxeira feito com molho de tomate caseiro, atum fresco e ervilha.', 44.05, 'Entradas', 'https://picsum.photos/seed/prod_loja_0001_09/200', true, '200ml', 0, 245),
